 /** The environment variable name for one field of a secret. */
 export function envName(path: string, field: string): string {
-  throw new Error("not implemented");
+  if (field === "") {
+    throw new RangeError("Field cannot be empty");
+  }
+  
+  // Get the last segment of the path
+  const segments = path.split("/");
+  const lastSegment = segments[segments.length - 1];
+  
+  // Combine last segment and field, then transform
+  const combined = `${lastSegment}_${field}`;
+  
+  // Replace runs of non-alphanumeric characters with single underscore
+  let name = combined.replace(/[^a-zA-Z0-9]+/g, "_");
+  
+  // Remove leading/trailing underscores
+  name = name.replace(/^_+|_+$/g, "");
+  
+  // Uppercase
+  name = name.toUpperCase();
+  
+  // Prefix with underscore if starts with digit
+  if (/^[0-9]/.test(name)) {
+    name = "_" + name;
+  }
+  
+  return name;
 }

